#include <bits/stdc++.h>
using namespace std;

int main() {
	// your code goes here
	int t;
	cin >> t;
	
	while(t--){
	    int n;
	    cin >> n;
	    
	    n *= 3;
	    
	    vector<long long>arr(n) , prefix(n+1);
	    
	    for(auto &x : arr){
	        cin >> x;
	    }
	    
	    sort(arr.begin() , arr.end());
	    
	    for(int i = 0 ; i < n ; i++){
	        prefix[i+1] = prefix[i] + arr[i];
	    }
	    
	    long long res = 3 * prefix[n];
	    
	    int m = n/3;
	    
	    for(int k = 0 ; k <= m ; k++){
	        int left = 0 , right = m-k;
	        
	        while(left < right){
	            int mid = (left + right)/2;
	            
	            long long d1 = arr[n-k-2*mid-2] + arr[n-k-2*mid-1] - 3LL * arr[2*k+mid];
	            
	            if(d1 > 0){
	                left = mid + 1;
	            }
	            else{
	                right = mid;
	            }
	        }
	        
	        for(int j = max(0 , left - 1) ; j <= min(m-k , left + 1) ; j++){
	            long long temp = 0;
	            
	            temp += 3LL * (prefix[n]-prefix[n-k]);
	            
	            temp += prefix[n-k] - prefix[n-k-2*j];
	            
	            temp -= 3LL * prefix[2 * k + j];
	            
	            res = max(res , 3LL * prefix[n] + temp);
	        }
	    }
	    
	    cout << res << endl;
	}

}
